def generate_csp_nonce():
    """Her istek için tek kullanımlık CSP nonce'u üret. Şablonlardaki satır-içi
    <script nonce="{{ csp_nonce }}"> blokları bu değerle imzalanır; başlıktaki
    nonce ile eşleşmeyen (örn. XSS ile enjekte edilen) script'ler çalışmaz."""
    g.csp_nonce = secrets.token_urlsafe(16)


def set_csp_header(response):
    """Content-Security-Policy başlığını uygula (nginx'ten buraya taşındı —
    nonce per-request üretildiği için statik nginx config'de yazılamaz).

    script-src: 'unsafe-inline' KALDIRILDI — satır-içi script blokları artık
    nonce ister. script-src-attr 'none': tüm satır-içi nitelik-handler'ları
    (onclick=...) yasak. Şablonlardaki/JS'teki on* işleyicileri data-action
    delegasyonuyla (static/actions.js) değiştirildi, böylece bu vektör tamamen
    kapatıldı; asıl enjeksiyon vektörü <script> blokları zaten nonce'a tabidir.
    img-src: 'https:' (tüm hostlar) yerine yalnızca S3 (pre-signed URL'ler,
    *.amazonaws.com) + data: (base64 profil/önizleme görselleri).
    Google Analytics (gtag.js, index.html): script/img/connect kaynakları
    Google'ın resmî CSP rehberindeki host setiyle açıldı."""
    nonce = getattr(g, "csp_nonce", "")
    # img-src: geniş `https://*.amazonaws.com` yerine yalnızca bu uygulamanın S3
    # kovası/bölgesi (config.CSP_IMG_S3_HOSTS). data: base64 avatar/önizleme için
    # gerekli olduğundan korunur.
    s3_src = (CSP_IMG_S3_HOSTS + " ") if CSP_IMG_S3_HOSTS else ""
    response.headers["Content-Security-Policy"] = (
        "default-src 'self'; "
        # SEC1: jsdelivr artık geniş `https://cdn.jsdelivr.net` host'u DEĞİL, yalnızca
        # SRI ile sabitlenmiş TAM dosyalar (chart.js + html5-qrcode). Kök/keyfi-yol
        # script yükleme kapandı; yeni bir jsdelivr varlığı eklenirse buraya da onun
        # tam sürümlü URL'i eklenmeli (aksi halde tarayıcı bloklar).
        # L7 (kabul edilen tradeoff): `https://*.googletagmanager.com` joker host'u
        # Google'ın resmî GA/gtag CSP rehberi gereği geniş bırakıldı (bölge/variant
        # gtag host'ları); daraltmak GA'yı kırabilir. Düşük risk olarak kabul edildi.
        f"script-src 'self' 'nonce-{nonce}' "
        "https://cdn.jsdelivr.net/npm/chart.js@4.4.7/dist/chart.umd.min.js "
        "https://cdn.jsdelivr.net/npm/html5-qrcode@2.3.8/html5-qrcode.min.js "
        "https://*.googletagmanager.com; "
        "script-src-attr 'none'; "
        # style-src: 'unsafe-inline' fallback yalnızca style-src-elem/-attr'ı
        # desteklemeyen ESKİ tarayıcılar için tutulur. Modern tarayıcılar daha
        # SIKI alt-direktifleri uygular:
        #   style-src-elem: <style> blokları + <link> stylesheet → 'unsafe-inline'
        #     KALDIRILDI; satır-içi <style> blokları artık per-request NONCE ister
        #     (XSS ile enjekte edilen <style> — CSS exfil/UI-redress vektörü — çalışmaz).
        #   style-src-attr 'unsafe-inline': dinamik style="..." nitelikleri (örn.
        #     progress-bar genişlikleri) nonce alamadığından kaçınılmaz; bu dar
        #     vektör açık kalır ama tam <style> enjeksiyonundan çok daha sınırlıdır.
        "style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; "
        f"style-src-elem 'self' 'nonce-{nonce}' https://fonts.googleapis.com; "
        "style-src-attr 'unsafe-inline'; "
        "font-src 'self' https://fonts.gstatic.com data:; "
        f"img-src 'self' data: {s3_src}"
        "https://*.google-analytics.com https://*.googletagmanager.com; "
        "connect-src 'self' https://*.google-analytics.com "
        "https://*.analytics.google.com https://*.googletagmanager.com; "
        "frame-ancestors 'none'; "
        "base-uri 'self'; "
        "form-action 'self'; "
        "object-src 'none'"
    )
    return response


